// Single source of truth. Exported JSON files are generated by scripts/export-schemas.cjs.
const base = "https://calendar-app.local/schemas/v1/";
const ref = (name) => ({ $ref: `${base}${name}.json` });
const text = (maxLength = 2000) => ({ type: "string", minLength: 1, maxLength, pattern: "\\S" });
const id = text(128);
const ids = (minItems = 0) => ({ type: "array", items: id, minItems, maxItems: 100, uniqueItems: true });
const strings = { type: "array", items: text(), maxItems: 20 };
const nullable = (schema) => ({ anyOf: [schema, { type: "null" }] });
const object = (properties) => ({ type: "object", additionalProperties: false, required: Object.keys(properties), properties });
const instant = { type: "string", format: "instant" };
const confidence = { enum: ["unknown", "low", "medium", "high"] };
const minutes = { type: "integer", minimum: 1, maximum: 525600 };
const fact = {
  oneOf: [
    object({ field: { const: "deadline" }, value: instant }),
    object({ field: { const: "status" }, value: { enum: ["open", "in_progress", "blocked", "completed", "cancelled"] } }),
    object({ field: { const: "effort_minutes" }, value: minutes }),
    object({ field: { const: "importance" }, value: { enum: ["low", "medium", "high"] } })
  ]
};
const definitions = {
  evidence: object({
    id,
    sourceType: { enum: ["journal", "user", "calendar", "document", "web", "activity", "history", "model"] },
    sourceId: id,
    sourceVersion: text(128),
    locator: nullable({ type: "string", format: "http-url", maxLength: 4096 }),
    excerpt: text(4000),
    observedAt: instant,
    sourceTimestamp: nullable(instant),
    verification: { enum: ["unverified", "source_matched", "user_confirmed"] },
    facts: { type: "array", items: fact, maxItems: 20 }
  }),
  task: object({
    id, title: text(500), description: { type: "string", maxLength: 4000 },
    status: { enum: ["open", "in_progress", "blocked", "completed", "cancelled"] },
    evidenceIds: ids(1),
    importance: object({ level: { enum: ["unknown", "low", "medium", "high"] },
      basis: { enum: ["unknown", "inferred", "user", "commitment"] }, reason: text(), evidenceIds: ids() }),
    deadline: nullable(object({ at: instant, kind: { enum: ["hard", "target"] }, evidenceIds: ids(1) })),
    estimateId: nullable(id),
    dependsOn: ids(),
    clarificationQuestions: strings
  }),
  estimate: object({
    id, taskId: id,
    scope: { enum: ["remaining_task", "next_session"] },
    basis: { enum: ["unknown", "personal_history", "project_estimate", "official_reference", "model", "local_heuristic"] },
    effortMinutes: nullable(object({ low: minutes, expected: minutes, high: minutes })),
    confidence,
    evidenceIds: ids(),
    assumptions: strings,
    rationale: text()
  }),
  plan: object({
    id, state: { const: "proposal" }, timezone: { type: "string", format: "iana-timezone" },
    targetDate: { type: "string", format: "calendar-date" },
    bufferMinutes: { type: "integer", minimum: 0, maximum: 1440 },
    availability: { type: "array", maxItems: 32, items: {
      type: "object", additionalProperties: false, required: ["startsAt", "endsAt"],
      properties: { label: text(100), startsAt: { type: "string", pattern: "^([01][0-9]|2[0-3]):[0-5][0-9]$" },
        endsAt: { type: "string", pattern: "^(([01][0-9]|2[0-3]):[0-5][0-9]|24:00)$" } }
    } },
    blocks: { type: "array", maxItems: 100, items: object({
      id, taskId: id, estimateId: id, startsAt: instant, endsAt: instant,
      effortMinutes: minutes, rationale: text(),
      calendarType: { enum: ["personal", "study", "vacation", "holiday", "birthday", "other"] },
      notifyMinutesBefore: { type: "integer", minimum: 0, maximum: 10080 },
      notificationFormat: text(200)
    }) },
    unscheduled: { type: "array", maxItems: 100, items: object({ taskId: id,
      reason: { enum: ["unknown_estimate", "insufficient_capacity", "blocked", "dependency", "needs_clarification", "inactive"] },
      explanation: text() }) },
    warnings: strings
  }),
  scheduling: object({
    version: { const: 1 }, algorithm: { const: "greedy-v1" },
    calendarFingerprint: { type: "string", pattern: "^[a-f0-9]{64}$" },
    settingsFingerprint: { type: "string", pattern: "^[a-f0-9]{64}$" },
    availabilitySource: { enum: ["settings", "request"] },
    notBefore: nullable(instant)
  }),
  bundle: object({
    schemaVersion: { const: 1 },
    evidence: { type: "array", maxItems: 100, items: ref("evidence") },
    tasks: { type: "array", maxItems: 100, items: ref("task") },
    estimates: { type: "array", maxItems: 100, items: ref("estimate") },
    plan: ref("plan")
  })
};
const schemas = Object.fromEntries(Object.entries(definitions).map(([name, definition]) => [name, {
  $schema: "http://json-schema.org/draft-07/schema#", $id: `${base}${name}.json`, title: `Calendar ${name} v1`, ...definition
}]));
module.exports = { schemas };
